SELECT COUNT(*)
FROM TB_PM07M01
WHERE 1=1

AND CO_CD = #{coCd}


AND REQ_DT BETWEEN #{reqDtFrom} AND #{reqDtTo}


AND VAC_TYPE_CD = #{vacTypeCd}


AND SANCTN_STS = #{sanctnSts}


AND REQ_ID = #{reqId}


AND REQ_DEPT_ID = #{reqDeptId}

SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT CO_CD, REQ_NO, REQ_DT, REQ_TITL, REQ_ID, REQ_DEPT_ID, VAC_TYPE_CD, (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = VAC_TYPE_CD) AS VAC_TYPE_NM, FN_CM06M01_ID_TO_NM(REQ_ID) AS REQ_ID_NM, (SELECT DEPT_NM FROM TB_CM04M01 WHERE DEPT_ID = REQ_DEPT_ID) AS REQ_DEPT_NM, AMPM_CD, TO_CHAR(TO_DATE(ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, TO_CHAR(TO_DATE(ST_TM, 'HH24MI'), 'HH24:MI') AS ST_TM, TO_CHAR(TO_DATE(ED_TM, 'HH24MI'), 'HH24:MI') AS ED_TM, VAC_DAYS, DEDUCT_DAYS, REQ_RMK, SANCTN_STS, WORK_RPT_YN, CREAT_ID, TO_CHAR(CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM07M01 WHERE 1=1
AND CO_CD = #{coCd}
AND REQ_DT BETWEEN #{reqDtFrom} AND #{reqDtTo}
AND VAC_TYPE_CD = #{vacTypeCd}
AND SANCTN_STS = #{sanctnSts}
AND REQ_ID = #{reqId}
AND REQ_DEPT_ID = #{reqDeptId}
ORDER BY REQ_DT DESC, REQ_NO DESC ) A ) WHERE RNUM BETWEEN #{firstIndex} AND #{lastIndex}

SELECT COUNT(*)
FROM TB_PM07M02
WHERE CO_CD = #{coCd} AND YY = #{yy} AND USER_ID = #{userId}


SELECT COUNT(*)
FROM TB_WB20M03
WHERE TODO_FILE_TRGT_KEY = #{fileTrgtKey}
AND TODO_CO_CD = #{coCd}
AND TODO_NO = #{reqNo}
AND TODO_DIV1_CODE_ID = 'TODODIV20'
AND SANCTN_STTUS = 'Y'

